const _jsonResponsePath="$['response']['data']['links']['next']";
const _base="{{_flow.SNYK_API_URL}}";
const _defaultValue=_base+"/rest/orgs/{{_flow.SNYK_ORG_ID}}/issues?version={{_flow.SNYK_API_VERSION}}&limit=100&status=open";
const _next = path(jsonContext, _jsonResponsePath);
return _next !== undefined ? (String(_next).indexOf("http")===0 ? _next : _base+_next) : _defaultValue;

actions.body:
{
  "jql": "project = {{_flow.SPACE}} AND \"cf[10156]\" ~ \"{{id}}\" AND statusCategory != Done ORDER BY created DESC",
  "maxResults": 5,
  "fields": [
    "summary",
    "status",
    "customfield_10156"
  ]
}

{
  "fields": {
    "project": {
      "key": "{{_flow.SPACE}}"
    },
    "summary": "Snyk {{attributes.effective_severity_level}}: {{{attributes.title}}}",
    "issuetype": {
      "name": "{{_flow.ISSUE_TYPE}}"
    },
    "labels": [
      "snyk",
      "snyk-{{attributes.effective_severity_level}}"
    ],
    "customfield_10156": "{{id}}",
    "description": {
      "type": "doc",
      "version": 1,
      "content": [
        {
          "type": "paragraph",
          "content": [
            {
              "type": "text",
              "text": "Snyk finding {{id}} ({{attributes.effective_severity_level}}) in organization {{_flow.SNYK_ORG_ID}}. Type: {{attributes.type}}. Status: {{attributes.status}}. Introduced: {{attributes.created_at}}."
            }
          ]
        },
        {
          "type": "paragraph",
          "content": [
            {
              "type": "text",
              "text": "Open in Snyk",
              "marks": [
                {
                  "type": "link",
                  "attrs": {
                    "href": "{{_flow.SNYK_APP_URL}}/org/{{_flow.SNYK_ORG_SLUG}}/project/{{attributes.coordinates.0.representations.0.dependency.package_name}}"
                  }
                }
              ]
            }
          ]
        }
      ]
    }
  }
}
